/* No.007 */
(() => {
const TEX = {"front": "front.jpg", "back": "back.jpg"};
const OUTLINE = [[-0.4436, -1.0], [0.4436, -1.0], [0.7636, -0.68], [0.7636, 0.68], [0.4436, 1.0], [-0.4436, 1.0], [-0.7636, 0.68], [-0.7636, -0.68]];
const FRAME_H = {"b16": 1, "n": 256, "x0": -1, "x1": 1, "y0": 1, "y1": -1, "h": ""};
const STONE = {"cx": 0.01, "cy": 0.07, "hw": 0.53, "hh": 0.71, "c": 0.15};
/* No.007 octagon frame with a Greek key band and an aurora-coated step-cut stone whose facets change colour with the angle */
function abStoneMat() {
  // clear acrylic: light passes through (transmission) and bends at the facets, so the foil underneath shows through.
  // The aurora coating is a thin film (iridescence) plus a soft facet tint that shifts with the angle.
  const m = new THREE.MeshPhysicalMaterial({
    color: 0xf6f4ff, metalness: 0, roughness: .02, transmission: 1, thickness: .22, ior: 1.5,
    iridescence: 1, iridescenceIOR: 1.8, iridescenceThicknessRange: [260, 820],
    specularIntensity: 1, envMapIntensity: 1.3, flatShading: true
  });
  m.onBeforeCompile = (sh) => {
    sh.fragmentShader = sh.fragmentShader.replace('#include <emissivemap_fragment>', `#include <emissivemap_fragment>
    {
      vec3 N = normalize(normal);
      vec3 V = normalize(vViewPosition);
      float nv = clamp(dot(N, V), 0.0, 1.0);
      float ph = nv * 1.9 + atan(N.y, N.x) * 0.2;
      vec3 ab = clamp(0.5 + 0.5 * cos(6.2832 * (ph + vec3(0.0, 0.36, 0.68))), 0.0, 1.0);
      vec3 Ls[3];
      Ls[0] = normalize(vec3(-2.0, 3.0, 4.0)); Ls[1] = normalize(vec3(2.6, 1.0, 3.0)); Ls[2] = normalize(vec3(0.3, -2.2, 3.0));
      float glint = 0.0;
      vec3 Rv = reflect(-V, N);
      for (int i = 0; i < 3; i++) glint += pow(max(dot(Rv, Ls[i]), 0.0), 10.0);
      totalEmissiveRadiance += ab * (0.04 + 0.4 * glint);
    }`);
  };
  return m;
}
function foilMat(map) {
  // what you see through the stone: the photo of the stone itself, lit as if light comes back off the foil
  return new THREE.MeshStandardMaterial({ map, emissiveMap: map, emissive: 0xffffff, emissiveIntensity: .45, metalness: .2, roughness: .35, envMapIntensity: .6 });
}
function stepCut(S, z0, layers) {
  // rings of the girdle outline, each smaller and higher; every side quad is split in two so the stone breaks into many facets
  const ring = (k, s, z) => {
    const hw = S.hw * s.x, hh = S.hh * s.y, c = S.c * Math.min(s.x, s.y);
    const p = [[-hw + c, -hh], [hw - c, -hh], [hw, -hh + c], [hw, hh - c], [hw - c, hh], [-hw + c, hh], [-hw, hh - c], [-hw, -hh + c]];
    return p.map(([x, y]) => [x + S.cx, y + S.cy, z]);
  };
  const R = layers.map((l, k) => ring(k, l.s, z0 + l.z));
  const pos = [];
  const tri = (a, b, c) => pos.push(...a, ...b, ...c);
  for (let k = 0; k < R.length - 1; k++) for (let i = 0; i < 8; i++) {
    const j = (i + 1) % 8, a = R[k][i], b = R[k][j], c = R[k + 1][j], d = R[k + 1][i];
    if ((i + k) % 2) { tri(a, b, c); tri(a, c, d); } else { tri(a, b, d); tri(b, c, d); }
  }
  const top = R[R.length - 1], cen = [S.cx, S.cy, z0 + layers[layers.length - 1].z];
  for (let i = 0; i < 8; i++) tri(top[i], top[(i + 1) % 8], cen);
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  g.computeVertexNormals();
  return g;
}
function buildG() {
  const grp = new THREE.Group();
  const FZ = .06, BZ = -.08;
  const frameMat = new THREE.MeshStandardMaterial({ map: tex(TEX.front), color: 0xf0e2c0, metalness: .85, roughness: .32, envMapIntensity: 1.2, side: THREE.DoubleSide });
  grp.add(new THREE.Mesh(cloverRelief(FRAME_H, FZ, .075), frameMat));
  const backMat = new THREE.MeshStandardMaterial({ map: tex(TEX.back), color: 0xf4e6c4, metalness: .8, roughness: .4, envMapIntensity: 1.1, side: THREE.DoubleSide });
  grp.add(new THREE.Mesh(cloverRelief(FRAME_H, BZ, 0, () => 0), backMat));
  // side walls
  const pos = [], idx = [], n = OUTLINE.length, sub = 12;
  for (let i = 0; i < n; i++) {
    const [ax, ay] = OUTLINE[i], [bx, by] = OUTLINE[(i + 1) % n];
    for (let t = 0; t < sub; t++) { const x = ax + (bx - ax) * t / sub, y = ay + (by - ay) * t / sub; pos.push(x, y, FZ + .002, x, y, BZ - .002); }
  }
  const m = pos.length / 6;
  for (let i = 0; i < m; i++) { const j = (i + 1) % m; idx.push(2 * i, 2 * j, 2 * i + 1, 2 * j, 2 * j + 1, 2 * i + 1); }
  const wg = new THREE.BufferGeometry(); wg.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3)); wg.setIndex(idx); wg.computeVertexNormals();
  grp.add(new THREE.Mesh(wg, new THREE.MeshStandardMaterial({ color: 0x9a8352, metalness: .9, roughness: .38, envMapIntensity: 1.1, side: THREE.DoubleSide })));
  // the stone
  grp.add(new THREE.Mesh(stepCut(STONE, FZ + .035, [
    { s: { x: 1, y: 1 }, z: 0 }, { s: { x: .88, y: .92 }, z: .06 }, { s: { x: .72, y: .82 }, z: .115 }, { s: { x: .5, y: .68 }, z: .155 }, { s: { x: .3, y: .56 }, z: .17 }
  ]), abStoneMat()));
  // the floor under the stone
  const S = STONE, hw = S.hw, hh = S.hh, c = S.c;
  const fs = new THREE.Shape([[-hw + c, -hh], [hw - c, -hh], [hw, -hh + c], [hw, hh - c], [hw - c, hh], [-hw + c, hh], [-hw, hh - c], [-hw, -hh + c]].map(([x, y]) => new THREE.Vector2(x + S.cx, y + S.cy)));
  const fg = new THREE.ShapeGeometry(fs);
  const fp = fg.attributes.position, fu = fg.attributes.uv;
  for (let i = 0; i < fp.count; i++) fu.setXY(i, fp.getX(i) / 2 + .5, fp.getY(i) / 2 + .5);
  fg.translate(0, 0, FZ + .026);
  grp.add(new THREE.Mesh(fg, foilMat(tex(TEX.front))));
  // box shank with a thread hole through it
  const s = new THREE.Shape();
  const w = .25, h = .3, r = .05;
  s.moveTo(-w, 0); s.lineTo(-w, h - r); s.quadraticCurveTo(-w, h, -w + r, h); s.lineTo(w - r, h); s.quadraticCurveTo(w, h, w, h - r); s.lineTo(w, 0); s.closePath();
  const hole = new THREE.Path(); hole.absarc(0, .17, .065, 0, Math.PI * 2, true); s.holes.push(hole);
  const sg = new THREE.ExtrudeGeometry(s, { depth: .3, bevelEnabled: true, bevelThickness: .012, bevelSize: .012, bevelSegments: 2, curveSegments: 16 });
  sg.rotateX(-Math.PI / 2); sg.translate(0, -.15, BZ);
  grp.add(new THREE.Mesh(sg, new THREE.MeshStandardMaterial({ color: 0xc9c2b2, metalness: 1, roughness: .28, envMapIntensity: 1.2 })));
  return grp;
}
buildG.env = 'jewel';
viewer(document.getElementById('cv'), buildG, 'v');
})();
